/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CurrentRunSaveExtract, CurrentRunCategoryCounts, CurrentRunCategory, CurrentRunMode, InRunLevelRow, InRunCategoryTotals, LifetimeFreeUpgradeCounts, InRunLevelsInput (+3 more)
 * depends    —
 * used by    src/save/current-run/in-run-levels, src/save/current-run/index, src/save/current-run/progress, src/save/current-run/read, src/save/history/access, src/save/history/timeline
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
/** Saved current-run arrays, retaining every position and unknown value. */
export interface CurrentRunSaveExtract {
  currentWave: number | null
  currentTier: number | null
  upgradeLevel: (number | null)[] | null
  upgradeDefenseLevel: (number | null)[] | null
  upgradeUtilityLevel: (number | null)[] | null
  /** Whether a run was in progress when the save was written, or `null` when the save does not say. */
  roundActive: boolean | null
  /** Real seconds played in this run so far. Time spent paused in the background is not in it. */
  realSeconds: number | null
  /** Game seconds this run so far: real seconds times the game speed in force. */
  gameSeconds: number | null
  /** Coins earned so far this run. */
  coinsSoFar: number | null
  /** Cells earned so far this run. */
  cellsSoFar: number | null
  /** Free upgrades that have landed this run, per workshop tab. */
  freeUpgrades: CurrentRunCategoryCounts
  unreadableKeys: string[]
}

/** A count per workshop tab, `null` where the source does not carry it. */
export interface CurrentRunCategoryCounts {
  attack: number | null
  defense: number | null
  utility: number | null
}

/** A workshop tab. */
export type CurrentRunCategory = 'attack' | 'defense' | 'utility'

/**
 * How a run in progress is being played: `afk` when every level above the workshop came from a
 * free upgrade, `active` when cash bought some, `unknown` when the counts cannot settle it.
 */
export type CurrentRunMode = 'afk' | 'active' | 'unknown'

/** One stat's level in the run in progress, set against its workshop level. */
export interface InRunLevelRow {
  category: CurrentRunCategory
  /** The stat, under the workshop table's name. */
  stat: string
  /** The permanent workshop level the run started from. */
  workshop: number
  /** The level in the run now. */
  inRun: number
  /** Levels above the workshop: `inRun - workshop`. */
  gained: number
  /**
   * How many of `gained` came from free upgrades and how many were bought with cash. The save
   * counts free upgrades per tab, not per stat, so these are known only when the whole tab is
   * one or the other; otherwise both are `null` and the tab's totals carry the split.
   */
  fromFree: number | null
  bought: number | null
}

/** One workshop tab's levels gained this run, split into free and bought. */
export interface InRunCategoryTotals {
  category: CurrentRunCategory
  /** Levels above the workshop, summed over the tab. */
  gained: number
  /** Free upgrades landed in this tab this run, or `null` when no source gives the count. */
  fromFree: number | null
  /** Levels bought with cash: `gained - fromFree`, never below zero. */
  bought: number | null
  /**
   * `exact` when the free count is this run's own; `upper-bound` when it was taken from lifetime
   * counters across two exports and may include an earlier run's upgrades.
   */
  freeCount: 'exact' | 'upper-bound' | 'missing'
}

/** Free-upgrade lifetime counters, per workshop tab. */
export interface LifetimeFreeUpgradeCounts {
  attack: number
  defense: number
  utility: number
}

/** What `resolveInRunLevels` reads. */
export interface InRunLevelsInput {
  currentRun: CurrentRunSaveExtract
  /** Workshop levels of the active preset, by workshop table name. */
  workshopLevels: Record<string, number>
  /** Lifetime free-upgrade counters at this export, for the fallback below. */
  lifetimeFree?: LifetimeFreeUpgradeCounts | null
  /**
   * Lifetime free-upgrade counters at an earlier export, used when the save carries no per-run
   * count. `atRunStart` says the earlier export was taken before this run gained any level, which
   * makes the difference exact; otherwise it is an upper bound.
   */
  earlier?: { lifetimeFree: LifetimeFreeUpgradeCounts, atRunStart: boolean } | null
}

/** The run in progress, one row per stat, and how it is being played. */
export interface InRunLevels {
  rows: InRunLevelRow[]
  categories: InRunCategoryTotals[]
  mode: CurrentRunMode
  warnings: string[]
}

/** What `resolveCurrentRunProgress` reads. */
export interface CurrentRunProgressInput {
  currentRun: CurrentRunSaveExtract
  /** When the save was written, as an ISO date. */
  exportedAt: string | null
  /** Lifetime play time in seconds at this export, for the fallback below. */
  playTimeSeconds?: number | null
  /** The last export taken before this run began, when the save carries no elapsed time. */
  beforeRun?: { exportedAt: string, playTimeSeconds: number } | null
}

/** Where a run in progress stands: its position, how long it has run and what it has earned. */
export interface CurrentRunProgress {
  tier: number | null
  wave: number | null
  /**
   * The latest moment the run can have started, as an ISO date: the export time less the real
   * seconds played. A run paused in the background started earlier than this.
   */
  startedAt: string | null
  realSeconds: number | null
  gameSeconds: number | null
  coinsSoFar: number | null
  cellsSoFar: number | null
  /** `save` when the save's own counters gave the time; `history` when two exports did. */
  source: 'save' | 'history' | null
  warnings: string[]
}
